'use strict';

/**
 * Uploads the game-assets folder (logos + sounds) to S3 so the app can
 * download them on demand via CloudFront — same bucket/domain that serves the
 * APK updates.
 *
 * Source folder (default): ../taddlebox-app/build/game-assets  (generated by
 * the app's asset pipeline — WebP logos + WAV sounds, ~1 MB total).
 * Target: s3://<S3_BUCKET_NAME>/game-assets/<...>  →  https://<CLOUDFRONT_DOMAIN>/game-assets/<...>
 *
 * Usage:
 *   node scripts/upload-game-assets.js [--dir <path>] [--no-clean]
 *
 * Env (same .env the server uses):
 *   AWS_REGION, AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, S3_BUCKET_NAME,
 *   CLOUDFRONT_DOMAIN (optional — only used for printing the public URLs).
 *
 * Default behavior is a true SYNC: objects under game-assets/ that no longer
 * exist locally are deleted. Pass --no-clean to keep them.
 */

require('dotenv').config();

const fs = require('fs');
const path = require('path');
const {
  PutObjectCommand,
  ListObjectsV2Command,
  DeleteObjectCommand,
} = require('@aws-sdk/client-s3');
const { s3Client, BUCKET_NAME, CLOUDFRONT_DOMAIN } = require('../src/config/s3');

// Mirrors the public URL scheme: /app-assets/games/<file> →
// s3://<S3_BUCKET_NAME>/app-assets/games/<file>.
const PREFIX = 'app-assets/games/';
const CACHE_CONTROL = 'public, max-age=31536000';
const DEFAULT_SRC = path.join(__dirname, '..', '..', 'taddlebox-app', 'build', 'game-assets');

const MIME_BY_EXT = {
  '.webp': 'image/webp',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.wav': 'audio/wav',
  '.mp3': 'audio/mpeg',
  '.json': 'application/json',
  '.svg': 'image/svg+xml',
};

function contentTypeFor(file) {
  return MIME_BY_EXT[path.extname(file).toLowerCase()] || 'application/octet-stream';
}

/** Recursively collect { localPath, relativeKey } for every file under dir. */
function collectFiles(dir, base = dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...collectFiles(full, base));
    } else {
      out.push({
        localPath: full,
        key: PREFIX + path.relative(base, full).split(path.sep).join('/'),
      });
    }
  }
  return out;
}

async function listRemoteKeys() {
  const keys = [];
  let token;
  do {
    const res = await s3Client.send(
      new ListObjectsV2Command({ Bucket: BUCKET_NAME, Prefix: PREFIX, ContinuationToken: token }),
    );
    for (const obj of res.Contents || []) keys.push(obj.Key);
    token = res.IsTruncated ? res.NextContinuationToken : undefined;
  } while (token);
  return keys;
}

async function main() {
  const args = process.argv.slice(2);
  const dirIdx = args.indexOf('--dir');
  const srcDir = dirIdx !== -1 && args[dirIdx + 1] ? path.resolve(args[dirIdx + 1]) : DEFAULT_SRC;
  const clean = !args.includes('--no-clean');

  if (!fs.existsSync(srcDir)) {
    console.error(`❌ Source folder not found: ${srcDir}`);
    console.error('   Generate it first (app repo): convert logos to WebP + copy sounds into build/game-assets/');
    process.exit(1);
  }
  if (!BUCKET_NAME) {
    console.error('❌ Missing S3_BUCKET_NAME in .env');
    process.exit(1);
  }

  const local = collectFiles(srcDir);
  console.log(`📦 Uploading ${local.length} files from ${srcDir} → s3://${BUCKET_NAME}/${PREFIX}`);

  let uploaded = 0;
  for (const { localPath, key } of local) {
    const command = new PutObjectCommand({
      Bucket: BUCKET_NAME,
      Key: key,
      Body: fs.createReadStream(localPath),
      ContentType: contentTypeFor(localPath),
      CacheControl: CACHE_CONTROL,
    });
    await s3Client.send(command);
    uploaded++;
    console.log(`  ✓ ${key}`);
  }

  if (clean) {
    const remoteKeys = await listRemoteKeys();
    const localKeys = new Set(local.map((f) => f.key));
    const stale = remoteKeys.filter((k) => !localKeys.has(k));
    for (const key of stale) {
      await s3Client.send(new DeleteObjectCommand({ Bucket: BUCKET_NAME, Key: key }));
      console.log(`  🗑  deleted stale ${key}`);
    }
    if (stale.length === 0) console.log('  (no stale objects to clean)');
  }

  console.log(`✅ Done — ${uploaded} files live.`);
  if (CLOUDFRONT_DOMAIN) {
    // The env value may already carry the scheme (e.g. https://bucket.s3...).
    const host = CLOUDFRONT_DOMAIN.replace(/^https?:\/\//, '');
    console.log(`   Public base URL: https://${host}/${PREFIX}`);
  }
}

main().catch((err) => {
  console.error('❌ Upload failed:', err);
  process.exit(1);
});
